const { useState } = React;
const root = ReactDOM.createRoot(document.querySelector('#root'));

let changeFromOutside = null;

const Card = () => {
  const [soldOut, setSoldOut] = useState(false);
  changeFromOutside = setSoldOut;

  return (
    <article className="card">
      <h3 className="card__title">오버사이즈 셔츠</h3>
      <p className="card__price">189,000원</p>
      {soldOut ? <p className="card__stock">품절</p> : null}
    </article>
  );
};

root.render(<Card />);

setTimeout(() => changeFromOutside(true), 3000);
